4.2 2. Data Loading & Standardization
Load the cruise dataset and scale numeric features.


Code
## I think these are "plain" names
## cruisenames_plain = c("SCOPE_16", ## G1
##                 "MGL1704", ## G2
##                 "KM1906", ## G3
##                 "TN397_740", ## G4
##                 "TN412_130") %&gt;% ## G5
##   .[2] ## Only G2 for now.


cruisenames = c("KOK1606", ## G1
                "MGL1704", ## G2
                "KM1906", ## G3
                "TN397", ## G4
                "TN412")  ## G5

for(cruisename in cruisenames){

  ## Print the markdown header for the tab
  cat_tab(cruisename)

  ## Load data
  filename = paste0( cruisename, "-X.csv")
  X &lt;- read.csv(file = file.path(datadir, filename))%&gt;% as_tibble()

  ## Extract spatiotemporal identifiers and scale numerical variables
  time0 &lt;- lubridate::as_datetime(X$time)
  lat0 &lt;- X %&gt;% pull(lat)
  lon0 &lt;- X %&gt;% pull(lon)
  varnames &lt;- X %&gt;% select(-c("time", "lat", "lon")) %&gt;% colnames()

  ## 1. First take the means and standard deviations
  means = X %&gt;% select(-time, -lat, -lon) %&gt;%
    summarise(across(everything(), ~mean(.x, na.rm = TRUE))) 
  sds = X %&gt;% select(-time, -lat, -lon) %&gt;%
    summarise(across(everything(), ~sd(.x, na.rm = TRUE))) 

  ## Base R plot
  apply(X[-c(1,2,3)], 2, mean, na.rm=TRUE) %&gt;% sort(decreasing=TRUE) %&gt;%
    plot(main = "Means of all variables, sorted")
  cat("\n\n") 

  ## 2. Then, identify which variables have really big means
  thresh = 1E10
  somenames = means[,which(means&gt;thresh & sds &gt; thresh)] %&gt;% names()
  if(length(somenames) &gt;= 1){

    ## 3. Visualize 
    p &lt;- X[,somenames] %&gt;%
      add_column(time = time0) %&gt;%
      pivot_longer(-time)  %&gt;% 
      ggplot() +
      geom_point(aes(x=time, y = value, group = name), size = .5) +
      facet_wrap(~name, scale = 'free_y')   +
      ggtitle("The unusually high-value variables")

    print(p)
    cat("\n\n") 

    ## 4. Remove these variables
    X = X %&gt;% select(-all_of(somenames))
  }

  ## Store the scaling information
  scaleobj &lt;- X %&gt;% select(-lat, -lon, -time) %&gt;% scale() 
  mean_val &lt;- attr(scaleobj, "scaled:center") %&gt;% unname()
  sd_val &lt;- attr(scaleobj, "scaled:scale") %&gt;% unname()

  ## Double check that scaling is sound
  scaled_data = as.matrix(scaleobj)
  unscaled_data &lt;- sweep(scaled_data, 2, sd_val, `*`)
  unscaled_data &lt;- sweep(unscaled_data, 2, mean_val, `+`)
  orig_matrix &lt;- as.matrix(X %&gt;% select(-time, -lat, -lon))

  ## Base R plot
  max_diffs &lt;- apply(abs(unscaled_data - orig_matrix), 2, max, na.rm = TRUE) %&gt;% sort()
  plot(max_diffs, type = "p", xlab = "Variables (Sorted)",
       ylab = "Max Absolute Difference",
       main = "Reconstruction Error per Variable")
  abline(h = 0, col = "red", lty = 2)
  cat("\n\n") 

  ## Save the scaling information
  filename = paste0(cruisename, "-cmap-scaling-info.RDS")
  X_scaled = scaled_data
  saveRDS(list(X_before_scaling = X,
               X_after_scaling = X_scaled,
               scaleobj = scaleobj,
               X_means = mean_val,
               X_sds = sd_val),
          file = file.path(outputdir, filename))

  ## Plot the initial scaled variables across time: 
  # X_combined &lt;- X_scaled %&gt;% as_tibble() %&gt;% mutate(time = time0,.before = 1)
  # scaled_plot &lt;- X_combined %&gt;% 
  #   pivot_longer(-time) %&gt;% 
  #   ggplot() +
  #   geom_path(aes(x = time, y = value, group = name), alpha = 0.1, linewidth = 0.1) +
  #   theme_minimal() +
  #   ggtitle("Scaled variables over time")
  # print(scaled_plot)


  ## Analyze missingness patterns across all variables.
  ## &gt; **Note:** Variables like salinity from GO-SHIP or GEOTRACES trajectories are naturally unavailable for non-targeted cruises ([GO-SHIP Paper](https://www.nature.com/articles/s41597-022-01212-w), [GEOTRACES Overview](https://www.geotraces.org/cruise-overview/)).


  ## Proportion of missing time points
  num_na &lt;- apply(X_scaled, 2, function(mycol) sum(is.na(mycol))) 
  ##print(head(sort(num_na, decreasing = TRUE)))

  num_time_points &lt;- nrow(X_scaled)
  prop_missing &lt;- num_na / num_time_points

  ## Missingness distribution histogram
  hist(prop_missing, breaks = 30, main = "Proportion of missing time points")
  abline(v = 0.25, col = "red", lty = 2)

  missing_only_few &lt;- sum(prop_missing &lt; 0.25)
  legend("topleft", legend = paste0("Missing only\na few:\n", missing_only_few, "\nvariables"), box.lwd = 0)

  missing_a_lot &lt;- sum(prop_missing &gt; 0.25)
  legend("topright", legend = paste0("Missing \na lot:\n", missing_a_lot, "\nvariables"), box.lwd = 0)


  ## Visualize the feature matrix before imputation (variables with $&lt;25\%$ missing values):
  X_scaled_copy0 &lt;- X_scaled %&gt;% as.matrix()
  dimnames(X_scaled_copy0) &lt;- NULL

  # heatmap &lt;- X_scaled_copy0 %&gt;% 
  #   .[, prop_missing &lt; 0.25] %&gt;% 
  #   drawmat_precise_ggplot() + 
  #   ggtitle("Matrix heatmap before imputation (&lt;25% missing)")
  # print(heatmap)

  ## Matrix Completion via Low-Rank SVD (`softImpute`); we'll
  ## fill missing values using nuclear-norm regularized singular value decomposition (`softImpute`).
  X_scaled_copy &lt;- X_scaled_copy0[, prop_missing &lt; 0.25] 

  if(sum(is.na(X_scaled_copy)) &gt;= 1){

    ## Fit nuclear-norm regularized SVD model
    fit &lt;- softImpute(X_scaled_copy, rank.max = 100, lambda = 10) ## I haven't carefully chosen lambda (or rank.max); we should do this..

    ## Complete matrix (fill NAs using low-rank fit)
    X_hat &lt;- complete(X_scaled_copy, fit, unscale = FALSE)

    ## Visualize the result
    # heatmap2 &lt;- drawmat_precise_ggplot(X_hat) +
    #   ggtitle("Matrix heatmap after softImpute low-rank completion")
    # print(heatmap2)

    ## Compare imputed entries against original observed series:
    X_smaller &lt;- X_scaled_copy
    observed_vec &lt;- as.vector(X_smaller)
    p &lt;- ncol(X_smaller)
    n &lt;- nrow(X_smaller)

    df &lt;- tibble(
      Time = rep(1:n, times = p),
      Series = rep(1:p, each = n),
      Value = as.vector(X_hat),
      Imputed_or_not = is.na(observed_vec)  
    )

    df_plot &lt;- df %&gt;%
      mutate(
        Series_Label = paste("Series", Series),
        Status = ifelse(Imputed_or_not, "Imputed", "Observed")
      )

    imputed_plot &lt;- df_plot %&gt;%
      group_by(Series) %&gt;%
      filter(any(Imputed_or_not)) %&gt;%
      ggplot(aes(x = Time, y = Value)) +
      geom_line(color = "gray50", linewidth = 0.5, alpha = 0.7) +
      geom_point(
        data = . %&gt;% filter(Imputed_or_not),
        aes(color = Status),
        size = 0.3
      ) +
      facet_wrap(~ Series_Label, scales = "free_y") +
      scale_color_manual(
        values = c("Imputed" = "firebrick", "Observed" = "gray30")
      ) +
      labs(
        title = "Time Series Imputation via softImpute",
        ##| fig-cap: "Comparison of observed vs. softImpute filled values across series"
        x = "Time Index",
        y = "Value",
        color = "Data Point"
      ) +
      theme_minimal() +
      theme(
        legend.position = "bottom",
        strip.text = element_text(face = "bold")
      )

    print(imputed_plot)

  } else {

    X_hat = X_scaled_copy0[, prop_missing &lt; 0.25]

  }

  ## Sanity check: confirm non-imputed entries were untouched:
  (X_scaled_copy0[, prop_missing &lt; 0.25] - X_hat) %&gt;% 
    as.numeric() %&gt;% 
    summary() %&gt;%
    as.list() %&gt;%
    as_tibble(check.names = FALSE)  %&gt;%
    make_html_table("Summary of the reconstruction errors") %&gt;% print()


  ## Format the imputed output, re-attach spatial coordinates, and aggregate to hourly resolution.
  varnames = colnames(X_scaled)
  remaining_names = varnames[prop_missing &lt; 0.25]
  colnames(X_hat) &lt;- remaining_names

  X_imputed &lt;- X_hat %&gt;% 
    as_tibble() %&gt;% 
    add_column(time = time0, lat = lat0, lon = lon0, .before = 1)

  X_imputed_hourly &lt;- X_imputed %&gt;% 
    group_by(time = lubridate::floor_date(time, "hour")) %&gt;%
    summarize(across(where(is.numeric), mean), .groups = "drop")

  # hourly_plot &lt;- X_imputed_hourly %&gt;% 
  #   select(-lat, -lon) %&gt;%
  #   pivot_longer(-time) %&gt;%
  #   ggplot() +
  #   geom_line(aes(x = time, y = value, group = name), col = "blue", alpha = 0.2, linewidth = 0.1) +
  #   scale_x_datetime(
  #       breaks = "1 day",
  #       labels = label_date("%b %d\n00:00") 
  #   ) +
  #   theme_minimal() +
  #   theme(panel.grid.minor.x = element_blank()) +
  #   ggtitle("Hourly aggregated variables over time")
  # print(hourly_plot)

  # hourly_plot_over_lat &lt;- X_imputed_hourly %&gt;% 
  #   pivot_longer(-c(time, lat, lon)) %&gt;% 
  #   ggplot(aes(x = lat, y = value, group = name)) +
  #   geom_path(col = "blue", linewidth = 0.1, alpha = 0.2) +
  #   theme_minimal() +
  #   ggtitle("Hourly aggregated variables plotted across latitude")
  # print(hourly_plot_over_lat)

  ## Save the imputed covariates in a single file;
  ## Saves to MGL1704-X-from-cmap-imputed-and-scaled.csv

  filename = paste0(cruisename, "-X-from-cmap-imputed-and-scaled.csv")
  write.csv(X_imputed_hourly,
            file = file.path(outputdir, filename),
            row.names = FALSE)
}




